+
+      const form = document.getElementById("support-form");
+      const status = document.getElementById("form-status");
+
+      const validators = {
+        fullName(value) {
+          if (!value.trim()) {
+            return "Error: Enter your full name.";
+          }
+          return "";
+        },
+        email(value) {
+          if (!value.trim()) {
+            return "Error: Enter your email address.";
+          }
+          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+          if (!emailPattern.test(value.trim())) {
+            return "Error: Enter a valid email address, like name@example.com.";
+          }
+          return "";
+        },
+        phone(value) {
+          if (!value.trim()) {
+            return "";
+          }
+          const phonePattern = /^\+?[0-9()\-\s]{7,20}$/;
+          if (!phonePattern.test(value.trim())) {
+            return "Error: Enter a valid phone number using the expected format.";
+          }
+          return "";
+        },
+      };
+
+      const setFieldState = (input, message) => {
+        const error = document.getElementById(input.id + "-error");
+        const isInvalid = Boolean(message);
+
+        input.classList.toggle("is-invalid", isInvalid);
+        input.setAttribute("aria-invalid", String(isInvalid));
+        error.textContent = message;
+      };
+
+      const validateField = (input) => {
+        const validator = validators[input.name];
+        const message = validator ? validator(input.value) : "";
+        setFieldState(input, message);
+        return !message;
+      };
+
+      form.querySelectorAll("input").forEach((input) => {
+        input.addEventListener("blur", () => {
+          validateField(input);
+        });
+
+        input.addEventListener("input", () => {
+          if (input.getAttribute("aria-invalid") === "true") {
+            validateField(input);
+          }
+          status.textContent = "";
+        });
+      });
+
+      form.addEventListener("submit", (event) => {
+        event.preventDefault();
+        status.textContent = "";
+
+        const inputs = Array.from(form.querySelectorAll("input"));
+        const firstInvalid = inputs.find((input) => !validateField(input));
+
+        if (firstInvalid) {
+          firstInvalid.focus();
+          return;
+        }
+
+        status.textContent = "Your support request is ready to send.";
+      });
+    </script>
+  </body>
+</html>
*** End Patch
