   <body>
     <a class="skip-link" href="#maincontent">Skip to main content</a>
     <main id="maincontent" tabindex="-1">
       <div id="app"></div>
     </main>

     <script>
       const fields = [
         {
           id: "fullName",
           name: "fullName",
           label: "Full name",
           type: "text",
           autocomplete: "name",
           required: true,
           placeholder: "Taylor Morgan",
           helper: "",
         },
         {
           id: "email",
           name: "email",
           label: "Email address",
           type: "email",
           autocomplete: "email",
           required: true,
           placeholder: "taylor@example.com",
           helper: "",
         },
         {
           id: "phone",
           name: "phone",
           label: "Phone number",
           type: "tel",
           autocomplete: "tel",
           required: false,
           placeholder: "+1 555 123 4567",
           helper: "Expected format: use digits, spaces, parentheses, or dashes, optionally starting with +.",
         },
       ];

       const fieldIds = (id) => ({
         helper: id + "-helper",
         error: id + "-error",
       });

       const Field = (field) => {
         const ids = fieldIds(field.id);
         const describedBy = [field.helper ? ids.helper : "", ids.error].filter(Boolean).join(" ");

         return `
           <div class="form-field">
             <label for="${field.id}">
               ${field.label}${field.required ? ' <span class="required-indicator" aria-hidden="true">*</span>' : ""}
             </label>
             <input
               id="${field.id}"
               name="${field.name}"
               type="${field.type}"
               ${field.required ? "required" : ""}
               autocomplete="${field.autocomplete}"
               aria-describedby="${describedBy}"
               aria-errormessage="${ids.error}"
               placeholder="${field.placeholder}"
             />
             ${field.helper ? `<p id="${ids.helper}" class="helper-text">${field.helper}</p>` : ""}
             <p id="${ids.error}" class="error-text" aria-live="polite"></p>
           </div>
         `;
       };

       const ContactForm = () => `
         <form id="support-form" novalidate>
           ${fields.map(Field).join("")}
           <div class="actions">
             <button type="submit">Send support request</button>
           </div>
           <p id="form-status" class="status-text" aria-live="polite"></p>
         </form>
       `;

       const SupportPage = () => `
         <section class="shell" aria-labelledby="page-title">
           <p class="eyebrow">Support</p>
           <h1 id="page-title">Contact our support team</h1>
           <p class="intro">
             Send us your details and we will follow up with the right next step for your issue.
           </p>
           <p class="required-note"><span aria-hidden="true">*</span> Required fields</p>
           ${ContactForm()}
         </section>
       `;

       document.getElementById("app").innerHTML = SupportPage();

       const form = document.getElementById("support-form");
       const status = document.getElementById("form-status");

       const validators = {
         fullName(value) {
           if (!value.trim()) {
             return "Error: Enter your full name.";
           }
           return "";
         },
         email(value) {
           if (!value.trim()) {
             return "Error: Enter your email address.";
           }
           const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
           if (!emailPattern.test(value.trim())) {
             return "Error: Enter a valid email address, like name@example.com.";
           }
           return "";
         },
         phone(value) {
           if (!value.trim()) {
             return "";
           }
           const phonePattern = /^\+?[0-9()\-\s]{7,20}$/;
           if (!phonePattern.test(value.trim())) {
             return "Error: Enter a valid phone number using the expected format.";
           }
           return "";
         },
       };

       const setFieldState = (input, message) => {
         const error = document.getElementById(input.id + "-error");
         const isInvalid = Boolean(message);

         input.classList.toggle("is-invalid", isInvalid);
         input.setAttribute("aria-invalid", String(isInvalid));
         error.textContent = message;
       };

       const validateField = (input) => {
         const validator = validators[input.name];
         const message = validator ? validator(input.value) : "";
         setFieldState(input, message);
         return !message;
       };

       form.querySelectorAll("input").forEach((input) => {
         input.addEventListener("blur", () => {
           validateField(input);
         });

         input.addEventListener("input", () => {
           if (input.getAttribute("aria-invalid") === "true") {
             validateField(input);
           }
           status.textContent = "";
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         status.textContent = "";

         const inputs = Array.from(form.querySelectorAll("input"));
         const firstInvalid = inputs.find((input) => !validateField(input));

         if (firstInvalid) {
           firstInvalid.focus();
           return;
         }

         status.textContent = "Your support request is ready to send.";
       });
     </script>
   </body>
 </html>

